def f(n):
    def factorial(i):
        if i == 0:
            return 1
        return i * factorial(i - 1)

    def sum_numbers(start, end):
        return end * (end + 1) // 2 - (start - 1) * start // 2

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_numbers(1, i))

    return result
